CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 integer, arg4 integer, arg5 integer, arg6 integer)
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE "Engineer_Visits"
    SET "visit_start_text" = arg2;

    IF arg4 <> -1000 THEN
        UPDATE "Engineer_Visits"
        SET "engineer_id" = arg1;
    END IF;

    IF arg4 = arg3 THEN
        UPDATE "Fault_Log_Parts"
        SET "fault_status" = 'Fixed'
        WHERE "part_fault_id" = arg4;
    END IF;

    IF arg1 < arg6 THEN
        UPDATE "Assets"
        SET "other_asset_details" = arg2
        WHERE "maintenance_contract_id" = arg6
          AND "supplier_company_id" = arg5;
    END IF;

    IF arg2 IS NOT NULL AND arg3 = arg5 THEN
        UPDATE "Parts" p
        SET "other_part_details" = arg2
        WHERE EXISTS (
            SELECT 1
            FROM "Part_Faults" pf
            WHERE pf."part_id" = p."part_id"
              AND pf."part_fault_id" = arg4
        );
    END IF;

    IF arg2 IS NOT NULL AND arg4 >= 0 THEN
        UPDATE "Fault_Log" fl
        SET "other_fault_details" = arg2
        WHERE EXISTS (
            SELECT 1
            FROM "Assets" a
            JOIN "Asset_Parts" ap ON ap."asset_id" = a."asset_id"
            JOIN "Part_Faults" pf ON pf."part_id" = ap."part_id"
            WHERE a."asset_id" = fl."asset_id"
              AND a."maintenance_contract_id" = arg6
              AND a."supplier_company_id" = arg5
              AND pf."part_fault_id" = arg4
        );
    END IF;
END;
$$;

